package com.rpb.reservation.workforce.approval;
import static com.rpb.reservation.workforce.approval.ApprovalDtos.*;
import com.rpb.reservation.workforce.application.WorkforceJson;
import com.rpb.reservation.workforce.domain.WorkforceException;
import java.sql.*;import java.time.*;import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository
public class ApprovalRepository {
 private final JdbcTemplate jdbc;private final WorkforceJson json;
 public ApprovalRepository(JdbcTemplate jdbc,WorkforceJson json){this.jdbc=jdbc;this.json=json;}
 public List<UUID> scheduleIds(UUID tenant,UUID store,UUID company,LocalDate from,LocalDate to){return scheduleIds(tenant,store,company,from,to,null);}
 public List<UUID> scheduleIds(UUID tenant,UUID store,UUID company,LocalDate from,LocalDate to,UUID employee){return jdbc.queryForList("select id from workforce_schedules where tenant_id=? and (?::uuid is null or store_id=?::uuid) and (?::uuid is null or company_id=?::uuid) and (?::uuid is null or employee_id=?::uuid) and work_date between ? and ? order by work_date,start_at,id limit 1001",UUID.class,tenant,store,store,company,company,employee,employee,from,to);}
 public List<UUID> allScheduleIds(UUID tenant,UUID store,UUID company,LocalDate from,LocalDate to){return jdbc.queryForList("select id from workforce_schedules where tenant_id=? and deleted_at is null and (?::uuid is null or store_id=?::uuid) and (?::uuid is null or company_id=?::uuid) and work_date between ? and ? order by work_date,start_at,id limit 50001",UUID.class,tenant,store,store,company,company,from,to);}
 public List<Approval> history(UUID tenant,UUID schedule){return jdbc.query("select * from workforce_approvals where tenant_id=? and schedule_id=? order by version desc",(r,n)->new Approval(r.getObject("schedule_id",UUID.class),r.getLong("version"),r.getString("source_fingerprint"),r.getLong("work_seconds"),r.getLong("paid_leave_seconds"),r.getLong("unpaid_leave_seconds"),json.read(r.getString("snapshot"),ApprovalSource.class),r.getObject("reviewer_id",UUID.class),r.getString("note"),r.getTimestamp("approved_at").toInstant(),r.getString("decisions")==null?null:List.of(json.read(r.getString("decisions"),ReviewDecision[].class))),tenant,schedule);}
 public Map<UUID,Approval> latest(UUID tenant,List<UUID> ids){if(ids.isEmpty())return Map.of();var args=new ArrayList<Object>();args.add(tenant);args.addAll(ids);var result=new HashMap<UUID,Approval>();var rows=jdbc.query("select distinct on(schedule_id) * from workforce_approvals where tenant_id=? and schedule_id in ("+String.join(",",Collections.nCopies(ids.size(),"?"))+") order by schedule_id,version desc",(r,n)->new Approval(r.getObject("schedule_id",UUID.class),r.getLong("version"),r.getString("source_fingerprint"),r.getLong("work_seconds"),r.getLong("paid_leave_seconds"),r.getLong("unpaid_leave_seconds"),json.read(r.getString("snapshot"),ApprovalSource.class),r.getObject("reviewer_id",UUID.class),r.getString("note"),r.getTimestamp("approved_at").toInstant(),r.getString("decisions")==null?null:List.of(json.read(r.getString("decisions"),ReviewDecision[].class))),args.toArray());rows.forEach(a->result.put(a.scheduleId(),a));return result;}
 public boolean managerAccount(UUID tenant,UUID account){if(account==null)return false;return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from auth_accounts a where a.tenant_id=? and a.id=? and (exists(select 1 from auth_account_roles r where r.account_id=a.id and r.deleted_at is null and r.role_code in ('tenant_admin','store_manager')) or exists(select 1 from workforce_administrators w where w.tenant_id=a.tenant_id and w.account_id=a.id and w.employee_manage=true)))",Boolean.class,tenant,account));}
 public void save(UUID tenant,UUID store,UUID employee,Approval a){jdbc.update("insert into workforce_approvals(tenant_id,store_id,schedule_id,employee_id,version,source_fingerprint,work_seconds,paid_leave_seconds,unpaid_leave_seconds,snapshot,reviewer_id,note,approved_at,decisions) values(?,?,?,?,?,?,?,?,?,?::jsonb,?,?,?,?::jsonb)",tenant,store,a.scheduleId(),employee,a.version(),a.sourceFingerprint(),a.workSeconds(),a.paidLeaveSeconds(),a.unpaidLeaveSeconds(),json.write(a.snapshot()),a.reviewerId(),a.note(),Timestamp.from(a.approvedAt()),a.decisions()==null?null:json.write(a.decisions()));}
 public void calendarLock(UUID tenant,UUID store){jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"workforce.calendar:"+tenant+":"+store);}
 public List<UUID> bounded(List<UUID> ids){if(ids.size()>1000)throw WorkforceException.invalid();return ids;}
}

